import unittest
from candidate import sum_to_n

class TestSumToN(unittest.TestCase):
    def test_sum_to_n_normal_case(self):
        self.assertEqual(sum_to_n(30), 465)

    def test_sum_to_n_large_number(self):
        self.assertEqual(sum_to_n(100), 5050)

    def test_sum_to_n_small_number(self):
        self.assertEqual(sum_to_n(5), 15)

    def test_sum_to_n_two(self):
        self.assertEqual(sum_to_n(10), 55)

    def test_sum_to_n_one(self):
        self.assertEqual(sum_to_n(1), 1)

    def test_sum_to_n_zero(self):
        self.assertEqual(sum_to_n(0), 0)

    def test_sum_to_n_negative_one(self):
        with self.assertRaises(TypeError):
            sum_to_n(-1)

    def test_sum_to_n_negative_number(self):
        with self.assertRaises(TypeError):
            sum_to_n(-5)

    def test_sum_to_n_non_integer_input(self):
        with self.assertRaises(TypeError):
            sum_to_n(3.14)

    def test_sum_to_n_none_input(self):
        with self.assertRaises(TypeError):
            sum_to_n(None)

    def test_sum_to_n_empty_range(self):
        self.assertEqual(sum_to_n(0), 0)

    def test_sum_to_n_single_element(self):
        self.assertEqual(sum_to_n(1), 1)

    def test_sum_to_n_large_positive(self):
        self.assertEqual(sum_to_n(1000), 500500)

    def test_sum_to_n_large_negative_input_behavior(self):
        with self.assertRaises(TypeError):
            sum_to_n(-100)
